package com.asmj.marketplace.controller;
import com.asmj.marketplace.complaints.*; import com.asmj.marketplace.model.*; import com.asmj.marketplace.order.*; import com.asmj.marketplace.repository.UserAccountRepository; import com.asmj.marketplace.notification.NotificationService;
import java.security.Principal; import java.time.Instant; import java.util.List; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class OrderComplaintController {
 private final OrderComplaintRepository complaints; private final MarketplaceOrderRepository orders; private final UserAccountRepository users; private final NotificationService notifications;
 public OrderComplaintController(OrderComplaintRepository c,MarketplaceOrderRepository o,UserAccountRepository u,NotificationService n){complaints=c;orders=o;users=u;notifications=n;}
 private UserAccount current(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();}
 @GetMapping("/customer/complaints") public String customerList(Principal p,Model m){m.addAttribute("complaints",complaints.findByCustomerUserIdOrderByCreatedAtDesc(current(p).getId()));return "customer/complaints";}
 @PostMapping("/customer/orders/{id}/complaints") public String create(@PathVariable String id,@RequestParam String subject,@RequestParam String description,Principal p,RedirectAttributes ra){UserAccount customer=current(p);MarketplaceOrder order=orders.findById(id).orElse(null);if(customer.getRole()!=Role.ROLE_CUSTOMER||order==null||!customer.getId().equals(order.getCustomerUserId()))return "auth/access-denied";if(subject==null||subject.isBlank()||subject.trim().length()>120||description==null||description.isBlank()||description.trim().length()>3000){ra.addFlashAttribute("errorMessage","Enter a subject and a description (maximum 3,000 characters).");return "redirect:/customer/orders";}if(complaints.existsByOrderIdAndCustomerUserIdAndStatusIn(id,customer.getId(),List.of(OrderComplaint.Status.OPEN,OrderComplaint.Status.UNDER_REVIEW,OrderComplaint.Status.WAITING_FOR_CUSTOMER))){ra.addFlashAttribute("errorMessage","You already have an open complaint for this order.");return "redirect:/customer/orders";}OrderComplaint c=new OrderComplaint();c.setOrderId(id);c.setOrderNumber(order.getOrderNumber());c.setCustomerUserId(customer.getId());c.setVendorUserId(order.getVendorUserId());c.setCustomerName(customer.getFullName());c.setSubject(subject.trim());c.setDescription(description.trim());c.setCreatedAt(Instant.now());c.setUpdatedAt(Instant.now());complaints.save(c);notifications.notifyAdmins("New order complaint","A customer raised a complaint for order "+order.getOrderNumber()+".","COMPLAINT",c.getId());notifications.notifyUser(order.getVendorUserId(),"Customer complaint received","A complaint was raised for order "+order.getOrderNumber()+".","COMPLAINT",c.getId());ra.addFlashAttribute("successMessage","Your complaint has been submitted to ASMJ Shoppe support.");return "redirect:/customer/complaints";}
 @GetMapping("/vendor/complaints") public String vendorList(Principal p,Model m){UserAccount vendor=current(p);m.addAttribute("complaints",complaints.findByVendorUserIdOrderByCreatedAtDesc(vendor.getId()));return "vendor/complaints";}
 @GetMapping("/admin/complaints") public String adminList(Model m){m.addAttribute("complaints",complaints.findAllByOrderByCreatedAtDesc());return "admin/complaints";}
 @PostMapping("/admin/complaints/{id}/update") public String update(@PathVariable String id,@RequestParam OrderComplaint.Status status,@RequestParam(required=false) String adminNote,RedirectAttributes ra){OrderComplaint c=complaints.findById(id).orElseThrow();c.setStatus(status);c.setAdminNote(adminNote==null?"":adminNote.trim().substring(0,Math.min(2000,adminNote.trim().length())));c.setUpdatedAt(Instant.now());complaints.save(c);notifications.notifyUser(c.getCustomerUserId(),"Complaint updated","Your complaint for order "+c.getOrderNumber()+" is now "+status+".","COMPLAINT",c.getId());ra.addFlashAttribute("successMessage","Complaint updated.");return "redirect:/admin/complaints";}
}
